        with self._lock:
            entry = self._entries.get(key)
            if entry is None:
                return False, None
            if not self._is_live(entry, time.time()):
                del self._entries[key]
                self._persist_locked()
                return False, None
            return True, entry["value"]

    def delete(self, key: str) -> bool:
        with self._lock:
            entry = self._entries.get(key)
            if entry is None:
                return False
            if not self._is_live(entry, time.time()):
