    args = parse_args()
    try:
        store = Store(args.data)
        server = KVHTTPServer((args.host, args.port), store)
    except (OSError, PersistenceError) as exc:
        print(f"fatal: {exc}", file=sys.stderr, flush=True)
        return 1

