            raise PersistenceError(f"cannot load data file {self.data_path}: {exc}") from exc

        now = time.time()
        self._entries = {
            key: entry for key, entry in loaded.items() if self._is_live(entry, now)
        }
        if len(self._entries) != len(loaded):
            self._persist_locked()

